package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Boolean;
    in attribute io_1 : Boolean;
    in attribute io_2 : Boolean;
    attribute stageIndex : Integer := 0;
    attribute paused : Boolean := true;
    attribute completed : Boolean := false;
    attribute prevIo0 : Boolean := false;
    attribute prevIo1 : Boolean := false;
    attribute prevIo2 : Boolean := false;
    attribute stage1RemainingMs : Integer := 0;
    attribute stage2RemainingMs : Integer := 0;
    attribute stage3RemainingMs : Integer := 0;
    attribute stage1ElapsedMs : Integer := 0;
    attribute stage2ElapsedMs : Integer := 0;
    attribute stage3ElapsedMs : Integer := 0;
    attribute totalElapsedMs : Integer := 0;
    perform action tick {
      first start;
      then if io_2 and not prevIo2 {
        first start;
        then assign paused := (if completed ? false else (not paused));
        then assign completed := false;
      }
      then if io_1 and not prevIo1 {
        first start;
        then assign stageIndex := (if stageIndex == 2 ? 0 else stageIndex + 1);
      }
      then if io_0 and not prevIo0 {
        first start;
        then if stageIndex == 0 {
          first start;
          then assign stage1RemainingMs := stage1RemainingMs + 1000;
        } else {
          first start;
          then if stageIndex == 1 {
            first start;
            then assign stage2RemainingMs := stage2RemainingMs + 1000;
          } else {
            first start;
            then assign stage3RemainingMs := stage3RemainingMs + 1000;
          }
        }
      }
      then if not completed and not paused {
        first start;
        then if stageIndex == 0 {
          first start;
          then if stage1RemainingMs <= 0 {
            first start;
            then assign stageIndex := (if stageIndex == 2 ? 2 else 1);
          }
        } else {
          first start;
          then if stageIndex == 1 {
            first start;
            then if stage2RemainingMs <= 0 {
              first start;
              then assign stageIndex := 2;
            }
          } else {
            first start;
            then if stageIndex == 2 {
              first start;
              then if stage3RemainingMs <= 0 {
                first start;
                then assign completed := true;
              }
            }
          }
        }
      }
      then assign prevIo0 := io_0;
      then assign prevIo1 := io_1;
      then assign prevIo2 := io_2;
    }
    out attribute io_3 : Boolean = completed;
    out attribute io_4 : Integer = (if completed ? 0 else 0);
    out attribute io_5 : Integer = (if completed ? 0 else (if stageIndex == 0 ? stage1RemainingMs else (if stageIndex == 1 ? stage2RemainingMs else stage3RemainingMs)));
    out attribute serial_0_trigger : Boolean = completed;
    out attribute serial_0_value_0 : Integer = totalElapsedMs;
    out attribute serial_0_value_1 : Integer = stage1ElapsedMs;
    out attribute serial_0_value_2 : Integer = stage2ElapsedMs;
    out attribute serial_0_value_3 : Integer = stage3ElapsedMs;
  }
  part system : Controller;
}
